import {CITIES,CITY,MODELS,MODEL,PROJECTS,HISTORICAL_ORDERS,SOURCES,GAUGES,POWERS} from './data.js';
import {CHAPTERS,CHARACTERS} from './story.js';
import * as E from './engine.js';
import {RailMap} from './map-v2.js';
import * as O from './operations.js';
import * as G from './gtfs.js';
import {REAL_STATIONS,REAL_TRAIN_CATALOGUE,COMMUTER_NETWORKS,REAL_DATA_SOURCES,REAL_DEPARTURES} from './assets/realdata.js';
import {RAIL_PATHS} from './assets/railways.js';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(x,d=0)=>Number(x||0).toLocaleString('es-ES',{maximumFractionDigits:d,minimumFractionDigits:d}),money=x=>n(x,1)+' M€',signed=x=>(x>=0?'+':'')+money(x),num=x=>n(x);
const names={operations:'Circulación del día',cercanias:'Cercanías y estaciones',timetables:'Horarios reales',trains:'Atlas de trenes',map:'Mapa de operaciones',story:'Modo historia',routes:'Red y servicios',fleet:'Flota y talleres',market:'Comprar trenes',projects:'Infraestructura',finance:'Finanzas',archive:'Archivo histórico'};
const icons={operations:'◷',cercanias:'C',timetables:'≡',trains:'▱',map:'⌖',story:'◇',routes:'⌁',fleet:'▤',market:'⊞',projects:'⚒',finance:'▥',archive:'▧'};
const KEY='iberia-ferroviaria-v1';let state=E.initialState(),screen='map',selected=null,speed=1,playing=false,timer=null,toastTimer=null,filter='',routeFilter='all',marketTab='catalogue',fleetTab='fleet',archiveTab='sources';let saved=null;let referenceCacheFeed=null,referenceCacheDate=null,referenceCacheTrips=[],referenceViewTrips=[];let dayTrips=[],referenceFeed=null,referenceTrips=[],referenceDate='',referenceRoute='',referenceSearch='',stationQuery='',networkId='madrid',trainQuery='',observing=false,referenceMinute=360;O.ensureOps(state);
try{const raw=localStorage.getItem(KEY);if(raw)saved=E.validateSave(JSON.parse(raw));}catch{}
const map=new RailMap($('map'),()=>state,id=>selectRoute(id),()=>({trips:observing?referenceViewTrips:state.ops?.phase==='running'?dayTrips:[],minute:observing?referenceMinute:state.ops?.phase==='running'?state.ops.minute:840}));
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500);}
function sourceLink(id){const s=SOURCES.find(x=>x.id===id);return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Consultar fuente oficial</a>`:'';}
function pause(){if(state.started)autosave();playing=false;clearInterval(timer);$('pause').textContent='▶';$('pause').setAttribute('aria-label','Reanudar jornada');}
function resume(){if(!state.started)return intro();if(state.ended)return toast('Tu mandato ha terminado.');if(E.pendingDecision(state))return showDecision();if($('modal').open)return;if(state.ops.phase==='review')return dayReview();observing=false;if(state.ops.phase==='planning')O.startDay(state);playing=true;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pausar jornada');dayTrips=O.servicePlan(state);autosave();render();clearInterval(timer);timer=setInterval(()=>advance(),240);}
function setSpeed(value){speed=value;document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',+b.dataset.speed===speed));if(playing)resume();}
function autosave(announce=false){try{localStorage.setItem(KEY,JSON.stringify(state));saved=E.validateSave(state);if(announce)toast('Partida guardada en este navegador. Puedes exportar una copia.');return true;}catch{if(announce)toast('El navegador no permite guardar aquí. Usa Exportar partida.');return false;}}
function act(fn,message){try{fn();if(message)toast(message);autosave();render();return true;}catch(error){toast(error.message);return false;}}
function advance(){if(!state.started)return intro();if(E.pendingDecision(state)){pause();showDecision();return;}if(state.ops.phase==='planning')O.startDay(state);if(state.ops.phase==='running'){const end=O.moveClock(state,5*speed);dayTrips=O.servicePlan(state);renderClock();if(screen==='operations')renderPanel();if(end){pause();O.endDay(state);autosave();render();dayReview();}}}
function showModal(html){pause();$('modal').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function closeModal(){if($('modal').open)$('modal').close();}
function modalHeader(title,eyebrow='CONSEJO DE DIRECCIÓN'){return `<div class="split"><span class="eyebrow">${esc(eyebrow)}</span><button class="close" data-action="close-modal" aria-label="Cerrar">×</button></div><h2>${esc(title)}</h2>`;}
function intro(){showModal(`<div class="modal-hero"><div class="portrait p1" role="img" aria-label="Raquel Sanz, ministra ficticia"></div><div class="modal-inner"><span class="eyebrow">CAMPAÑA · 2022–2050</span><h2>El próximo tren<br>lo decides tú.</h2><p>Enero de 2022. España vuelve a moverse. Asumes la dirección de una Renfe que necesita recuperar servicios, renovar sus trenes y volver a ganarse al viajero.</p><div class="intro-badges"><span class="tag">Mapa de España</span><span class="tag">5 capítulos</span><span class="tag">28 años de decisiones</span></div><p class="small">Historia alternativa apoyada en proyectos y contratos reales. La venta masiva de flota y el cierre inicial son ficción. Las cifras económicas son de juego.</p><div class="actions">${saved?'<button class="primary" data-action="continue">Continuar partida</button>':''}<button class="${saved?'ghost':'primary'}" data-action="begin">Asumir la dirección</button></div><p class="small muted" style="margin-top:18px">Se guarda en este navegador. También puedes exportar tu partida.</p></div></div>`);}
function showDecision(){const d=E.pendingDecision(state);if(!d)return;const person=CHARACTERS[d.person];showModal(`<div class="modal-hero"><div class="portrait p${person.portrait}" role="img" aria-label="${esc(person.name)}"></div><div class="modal-inner"><span class="eyebrow">${esc(E.dateOf(state.month))} · DECISIÓN</span><h2>${esc(d.title)}</h2><p>${esc(d.body)}</p><p class="small" style="margin-top:14px;color:var(--gold)">${esc(person.name)} · diálogo ficticio</p>${d.choices.map((c,i)=>`<button class="choice" data-action="decision" data-id="${d.id}" data-choice="${i}" ${state.cash<-(c.effects.cash||0)?'disabled':''}><strong>${esc(c.label)}</strong><span>${esc(c.detail)}</span></button>`).join('')}<div class="small muted" style="margin-top:16px">${d.source?sourceLink(d.source)+' · decisiones y efectos simulados':'Escenario ficticio de la campaña'}</div></div></div>`);}
function objectives(c,large=false){return `<div class="objectives">${c.objectives.map(([key,target,title])=>{const v=E.objectiveValue(state,key);return `<div class="objective"><span class="check ${v>=target?'done':''}">${v>=target?'✓':''}</span><span>${esc(title)}</span><span class="count">${key==='solvent'?(v?'✓':'—'):num(Math.min(v,target))+' / '+target}</span></div>`;}).join('')}</div>`;}
function mission(){const c=CHAPTERS[state.chapter];$('mission').innerHTML='<button class="mission-summary" data-action="navigate" data-screen="story"><span class="eyebrow">CAPÍTULO '+(state.chapter+1)+'</span><strong>'+esc(c.title)+'</strong><span>'+c.objectives.filter(([key,target])=>E.objectiveValue(state,key)>=target).length+' / '+c.objectives.length+' objetivos</span></button>';}
function render(){for(const element of document.querySelectorAll('.map-tools,.layer-switch,.map-title,.map-legend,.map-credit,#map,#dayDock'))element.inert=screen!=='map';$('dayDock').classList.toggle('hidden',screen!=='map');O.ensureOps(state);dayTrips=O.servicePlan(state);map.dirty=true;const b=E.balance(state);$('date').textContent=state.ended&&state.ending==='2050'?'31 dic 2050':O.dayLabel(state);$('resources').innerHTML=`<div class="resource"><small>TESORERÍA</small><strong>${money(state.cash)}</strong><span class="trend">${signed(b.net)}/mes</span></div><div class="resource"><small>VIAJEROS / MES</small><strong>${n(b.passengers/1000,1)} mil</strong></div><div class="resource"><small>SATISFACCIÓN</small><strong>${n(state.satisfaction)}<span style="font-size:13px"> %</span></strong></div>`;$('navigation').innerHTML=Object.keys(names).map(k=>`<button class="nav-button ${screen===k?'active':''}" data-action="navigate" data-screen="${k}" title="${names[k]}" aria-label="${names[k]}" ${screen===k?'aria-current="page"':''}>${icons[k]}<span>${names[k]}</span></button>`).join('');$('bottomStats').innerHTML=[['SERVICIOS EN MARCHA',state.routes.filter(r=>r.active).length+' / '+state.routes.length],['TRENES DISPONIBLES',state.fleet.reduce((v,f)=>v+E.available(state,f),0)],['RESULTADO MENSUAL',signed(b.net)],['PUNTUALIDAD',n(b.punctuality)+' %']].map(([k,v])=>`<div class="bottom-stat"><small>${k}</small><strong>${v}</strong></div>`).join('');$('mapSubtitle').textContent=state.month<12?'Recupera los servicios. Vuelve a ganarte al viajero.':`${state.routes.filter(r=>r.active).length} servicios. Un país que vuelve a moverse.`;const last=state.log[0];$('tickerText').textContent=last?last.title+' · '+last.body:'';mission();$('panel').classList.toggle('hidden',screen==='map');$('mission').classList.toggle('hidden',screen!=='map'||!!selected);$('routePanel').classList.toggle('hidden',!selected||screen!=='map');if(screen!=='map')renderPanel();if(selected&&screen==='map')renderRoute();renderClock();}
function navigate(to){pause();if(to!=='map')observing=false;screen=names[to]?to:'map';selected=null;filter='';$('routePanel').classList.add('hidden');render();}
function header(title,text='',kicker='DIRECCIÓN DE RENFE'){return `<div class="panel-header"><div><span class="eyebrow">${kicker}</span><h2>${title}</h2>${text?`<p>${text}</p>`:''}</div><button class="close" data-action="navigate" data-screen="map" aria-label="Cerrar panel">×</button></div>`;}
function renderPanel(){const pages={operations:operationsPage,cercanias:cercaniasPage,timetables:timetablesPage,trains:trainsPage,story:storyPage,routes:routesPage,fleet:fleetPage,market:marketPage,projects:projectsPage,finance:financePage,archive:archivePage};$('panel').innerHTML=pages[screen]?.()||'';if(screen==='finance')drawChart();}
function storyPage(){const c=CHAPTERS[state.chapter],person=CHARACTERS[c.speaker];return header('Tu mandato, tu historia.','Recuperar un país es una sucesión de decisiones. Cada capítulo desbloquea financiación para el siguiente.','CAMPAÑA 2022–2050')+`${state.ended?`<div class="ending"><span class="eyebrow">${state.ending==='2050'?'31 DE DICIEMBRE DE 2050':'INTERVENCIÓN DE LA COMPAÑÍA'}</span><h2>Tu legado: ${E.finalScore(state)} / 100</h2><p>${E.finalScore(state)>=80?'Has dejado una red extensa, fiable y con futuro.':E.finalScore(state)>=50?'Has recuperado conexiones importantes. Quedan desequilibrios por resolver.':'La recuperación no ha alcanzado sus objetivos. Cada decisión será una lección para el próximo mandato.'}</p><p>${state.routes.filter(r=>r.active).length} servicios · ${n(state.stats.passengers/1e6,1)} millones de viajes · ${n(state.satisfaction)}% de satisfacción · ${money(state.cash-state.debt)} de caja neta de deuda.</p></div>`:''}<div class="timeline">${CHAPTERS.map((c,i)=>`<div class="stage ${i===state.chapter?'active':''}"><small>${state.claimed.includes(c.id)?'✓ ':''}${c.years}</small><h3>0${i+1} · ${c.title}</h3></div>`).join('')}</div><div class="chapter-detail"><div class="portrait p${person.portrait}" role="img" aria-label="${person.name}"></div><div><span class="eyebrow">${person.name} · PERSONAJE FICTICIO</span><h2>${c.title}</h2><p>${c.text}</p>${objectives(c,true)}<div class="actions"><button class="primary" data-action="claim" ${!E.chapterReady(state)||state.ended?'disabled':''}>${state.claimed.includes(c.id)?'Capítulo completado':'Reclamar '+c.reward+' M€'}</button><button data-action="navigate" data-screen="routes">Gestionar servicios</button></div>${E.yearOf(state)<c.year?`<div class="info">Esta etapa comienza en ${c.year}. Puedes preparar sus objetivos mientras tanto.</div>`:''}</div></div><div class="info">Los capítulos pueden completarse después de sus fechas orientativas. La campaña termina al cerrar diciembre de 2050. Las escenas políticas y las decisiones son ficción; el archivo distingue datos y simulación.</div><div class="actions"><button data-action="save-dialog">Guardar / exportar</button><button class="danger" data-action="new-game">Nueva campaña</button></div>`;}
function routesPage(){let list=state.routes.filter(r=>(!filter||E.routeName(r).toLowerCase().includes(filter.toLowerCase()))&&(routeFilter==='all'||(routeFilter==='active'?r.active:routeFilter==='closed'?!r.active&&E.isUnlocked(state,r):!E.isUnlocked(state,r))));return header('Red y servicios','La infraestructura no basta: asigna trenes, fija salidas por sentido y elige una tarifa. Abrir un servicio cuesta 4 M€.')+`<div class="toolbar"><input id="routeSearch" placeholder="Buscar ciudad o servicio…" aria-label="Buscar servicio" value="${esc(filter)}"><div class="tabs">${[['all','Todos'],['active','En servicio'],['closed','Recuperables'],['works','En obras']].map(([id,name])=>`<button data-action="route-filter" data-value="${id}" class="${routeFilter===id?'active':''}">${name}</button>`).join('')}</div></div><div class="table-wrap"><table><thead><tr><th>SERVICIO</th><th>ESTADO</th><th>VIAJEROS / MES</th><th>RESULTADO</th><th></th></tr></thead><tbody>${list.map(r=>{const b=E.metrics(state,r),unlocked=E.isUnlocked(state,r);return `<tr><td><strong>${esc(E.routeName(r))}</strong><small>${r.km} km · ${GAUGES[r.gauge]}${r.custom?' · hipotética':''}</small></td><td><span class="tag ${r.active?'green':''}">${r.active?'En servicio':unlocked?'Por recuperar':'Infraestructura'}</span></td><td>${r.active?num(b.passengers):'—'}</td><td class="${b.net>=0?'positive':'negative'}">${r.active?signed(b.net):'—'}</td><td><button class="row-button" data-action="route" data-id="${r.id}">Gestionar</button></td></tr>`;}).join('')}</tbody></table></div>${!list.length?'<div class="empty">No hay servicios que coincidan con la búsqueda.</div>':''}`;}
function selectRoute(id){pause();observing=false;selected=id;screen='map';map.focus(id,true);render();}
function fleetOption(f,r){const m=MODEL[f.model],available=E.available(state,f,r.id);return `<option value="${f.id}" ${r.fleet===f.id?'selected':''}>${esc(m.name)} · ${available} libres · ${n(f.condition)}%</option>`;}
function renderRoute(){const r=state.routes.find(r=>r.id===selected);if(!r)return;const unlocked=E.isUnlocked(state,r),compatible=state.fleet.filter(f=>f.qty>0&&E.compatible(r,MODEL[f.model]));const m=E.metrics(state,r);$('routePanel').innerHTML=`<button class="close" data-action="close-route" aria-label="Cerrar servicio">×</button><span class="eyebrow">${r.custom?'TU NUEVA LÍNEA':'GESTIÓN DEL SERVICIO'}</span><h2>${esc(E.routeName(r))}</h2><span class="tag ${r.active?'green':''}">${r.active?'En servicio':unlocked?'Listo para recuperar':r.availableFrom?'Disponible '+r.availableFrom:'Pendiente de infraestructura'}</span><div class="route-info"><div><small>DISTANCIA GEOGRÁFICA APROX.</small><strong>${r.km} km</strong></div><div><small>VELOCIDAD DE LÍNEA</small><strong>${r.speed} km/h</strong></div><div><small>ANCHO DE VÍA</small><strong>${GAUGES[r.gauge]}</strong></div><div><small>TRACCIÓN</small><strong>${r.power==='electric'?'Electrificada':'Sin electrificar'}</strong></div></div>${!unlocked?`<div class="info">${r.project?'Necesitas completar el proyecto de infraestructura asociado.':'Disponible a partir de '+E.dateOf(r.unlock)+'. Apertura histórica simplificada al mes.'}</div><button data-action="navigate" data-screen="projects">Ver infraestructura</button>`:`<form id="routeForm"><label for="routeFleet">Material asignado</label><select id="routeFleet" required>${compatible.length?compatible.map(f=>fleetOption(f,r)).join(''):'<option value="">No hay material compatible</option>'}</select><div class="form-grid"><div><label for="frequency">Salidas / sentido / día</label><input id="frequency" type="number" min="1" max="${r.kind==='commuter'?64:16}" step="1" value="${r.frequency}" required></div><div><label for="fare">Tarifa media (€)</label><input id="fare" type="number" min="2" max="150" step="1" value="${r.fare}" required></div></div><div class="form-grid"><div><label for="firstDeparture">Primera salida</label><input id="firstDeparture" type="time" value="${O.clockText(r.first??(r.kind==='commuter'?330:360))}" required></div><div><label for="lastDeparture">Última salida</label><input id="lastDeparture" type="time" value="${O.clockText(r.last??(r.kind==='commuter'?1410:1260))}" required></div></div><div id="routePreview" class="info"></div><button class="primary" type="submit" ${!compatible.length||state.ended?'disabled':''}>${r.active?'Aplicar plan de servicio':'Reabrir servicio · 4 M€'}</button></form><div class="actions"><button data-action="upgrade" data-id="${r.id}" ${r.level>=3||state.ended?'disabled':''}>Mejorar · ${12+12*r.level} M€</button>${r.active?`<button class="danger" data-action="close-service" data-id="${r.id}" ${state.ended?'disabled':''}>Suspender</button>`:''}</div><div class="small muted" style="margin-top:12px">Nivel de servicio ${r.level}/3. Una mejora tarda 4 meses y aumenta atractivo y fiabilidad.</div>`}<hr class="divider"><h3>Frente a la carretera</h3><div class="route-info"><div><small>VIAJEROS / MES</small><strong>${num(m.passengers)}</strong></div><div><small>OCUPACIÓN</small><strong>${n(m.occupancy*100)}%</strong></div><div><small>RENFE · CUOTA SIMULADA</small><strong>${n(m.share*100)}%</strong></div><div><small>ALSA · CUOTA SIMULADA</small><strong>${n(m.busShare*100)}%</strong></div><div><small>RESULTADO MENSUAL</small><strong class="${m.net>=0?'positive':'negative'}">${signed(m.net)}</strong></div><div><small>OTROS MODOS / OPERADORES</small><strong>${n(m.otherShare*100)}%</strong></div></div><p class="small muted">Las cuotas comparan atractivo de precio, tiempo, frecuencia y fiabilidad. No son cuotas reales publicadas. ${r.custom?'Trazado conceptual entre ciudades; requiere estudio real fuera del juego.':''}</p>`;if(unlocked)updateRoutePreview();const work=state.projects.find(p=>!p.done&&(p.route===r.id||PROJECTS.find(d=>d.id===p.id)?.routes.includes(r.id)));if(work){const ws=O.constructionStatus(state,work);$('routePanel').insertAdjacentHTML('beforeend',`<hr class="divider"><h3>Visita de obra</h3><p>${ws.stage} · ${n(ws.progress*100)}%</p><div class="progress"><span style="width:${ws.progress*100}%"></span></div><p class="small">Fin de juego: ${E.dateOf(work.due)}. Las fases y su distribución espacial son simuladas.</p>`);} $('routePanel').insertAdjacentHTML('beforeend',`<p class="small muted">${RAIL_PATHS[r.id]?'Recorrido calculado sobre vías OSM; selección operativa aproximada.':'Enlace conceptual: no se dispone de un recorrido verificado para esta conexión.'}</p>`);}
function updateRoutePreview(){const r=state.routes.find(r=>r.id===selected),f=state.fleet.find(f=>f.id===$('routeFleet')?.value);if(!r||!f||!$('routePreview'))return;const frequency=+$('frequency').value,fare=+$('fare').value,m=MODEL[f.model];const units=E.requiredUnits({...r,first:parseClock($('firstDeparture')?.value||'06:00'),last:parseClock($('lastDeparture')?.value||'21:00')},m,frequency),b=E.metrics(state,r,{active:true,fleet:f.id,frequency,fare,units});$('routePreview').innerHTML=`${units} tren${units===1?'':'es'} necesario${units===1?'':'s'} · ${E.available(state,f,r.id)} disponible${E.available(state,f,r.id)===1?'':'s'}<br>Previsión: ${num(b.passengers)} viajeros/mes · <strong class="${b.net>=0?'positive':'negative'}">${signed(b.net)}/mes</strong>`;}
function fleetPage(){return header('Los trenes que hacen posible la red.','Las unidades asignadas no pueden venderse ni entrar en reforma. Libéralas reduciendo frecuencias o suspendiendo el servicio.')+`<div class="toolbar"><div class="tabs"><button data-action="fleet-tab" data-value="fleet" class="${fleetTab==='fleet'?'active':''}">Parque de material</button><button data-action="fleet-tab" data-value="workshop" class="${fleetTab==='workshop'?'active':''}">Talleres</button></div><button data-action="navigate" data-screen="market">Comprar trenes</button></div>${fleetTab==='workshop'?`<div class="info">Una reforma cuesta el 12% del precio base y dura 5 meses. Devuelve el estado al 98%, conservando la edad del vehículo.</div><div class="grid">${state.refits.map(r=>`<div class="card"><span class="tag ${r.done?'green':''}">${r.done?'Completada':'En taller'}</span><h3>${MODEL[r.model].name}</h3><p>${r.qty} unidades · salida ${E.dateOf(r.due)}</p></div>`).join('')}</div>${!state.refits.length?'<div class="empty">Aún no hay trenes en reforma. En Parque de material, elige un lote con unidades libres.</div>':''}`:`<div class="table-wrap"><table><thead><tr><th>MATERIAL</th><th>PARQUE</th><th>LIBRES</th><th>ESTADO</th><th></th></tr></thead><tbody>${state.fleet.filter(f=>f.qty>0).map(f=>`<tr><td><strong>${MODEL[f.model].name}</strong><small>${esc(f.origin)} · desde ${f.born}</small></td><td>${f.qty}</td><td>${E.available(state,f)}</td><td><span class="${f.condition<50?'negative':'positive'}">${n(f.condition)}%</span></td><td><button class="row-button" data-action="fleet-detail" data-id="${f.id}">Gestionar lote</button></td></tr>`).join('')}</tbody></table></div>`}`;}
function fleetDetail(id){const f=state.fleet.find(f=>f.id===id),m=MODEL[f.model];showModal(`<div class="modal-inner">${modalHeader(m.name,'FLOTA Y TALLERES')}<p>${GAUGES[m.gauge]} · ${POWERS[m.power]} · ${m.speed} km/h</p><div class="specs"><div><small>LOTE</small>${f.qty} unidades</div><div><small>LIBRES</small>${E.available(state,f)}</div><div><small>ESTADO</small>${n(f.condition)}%</div></div><label for="fleetQty">Unidades libres que quieres gestionar</label><input id="fleetQty" type="number" min="1" max="${E.available(state,f)}" value="${Math.min(2,E.available(state,f))}" step="1"><div class="info">Reforma: ${money(m.price*.12)} por unidad · 5 meses.<br>Venta: aproximadamente ${money(m.price*.23*f.condition/100)} por unidad.<br>La venta retira inmediatamente esas unidades del parque.</div><div class="actions"><button class="primary" data-action="refurbish" data-id="${id}" ${!E.available(state,f)||state.ended?'disabled':''}>Enviar a reforma</button><button class="danger" data-action="sell" data-id="${id}" ${!E.available(state,f)||state.ended?'disabled':''}>Vender unidades</button></div></div>`);}
function marketPage(){return header('Un buen pedido se hace con tiempo.','Anticipo del 30%; el 70% restante se abona por lote a la entrega. Plazos variables por carga industrial, tamaño de pedido y retrasos de homologación.')+`<div class="toolbar"><div class="tabs"><button data-action="market-tab" data-value="catalogue" class="${marketTab==='catalogue'?'active':''}">Catálogo</button><button data-action="market-tab" data-value="orders" class="${marketTab==='orders'?'active':''}">Mis pedidos</button><button data-action="market-tab" data-value="historical" class="${marketTab==='historical'?'active':''}">Contratos históricos</button></div></div>${marketTab==='catalogue'?`<div class="info">Precios y plazos de catálogo son parámetros de juego, no ofertas de los fabricantes. Los modelos antiguos representan posibles reediciones hipotéticas. No se cobra otra vez un contrato histórico.</div><div class="grid">${MODELS.map(m=>{const unlocked=E.yearOf(state)>=m.year;return `<article class="card"><div class="split"><span class="eyebrow">${m.maker}</span><span class="tag ${unlocked?'green':''}">${unlocked?m.category:'Desde '+m.year}</span></div><div class="train-code">${m.name.split(' · ')[0]}</div><h3>${m.name.split(' · ')[1]||m.name}</h3><p>${m.desc}</p><div class="specs"><div><small>VELOCIDAD</small>${m.speed} km/h</div><div><small>CAPACIDAD*</small>${num(m.seats)}</div><div><small>PLAZO BASE</small>${m.lead} meses</div></div><p class="small">${GAUGES[m.gauge]} · ${POWERS[m.power]}</p><div class="card-foot"><strong>${money(E.purchaseQuote(state,m.id,1).total)}</strong><button data-action="purchase" data-id="${m.id}" ${!unlocked||state.ended?'disabled':''}>Configurar pedido</button></div></article>`;}).join('')}</div><p class="small muted" style="margin-top:20px">* Capacidad de simulación. Cercanías incluye plazas de pie. Longitudes de andén y subseries se simplifican.</p>`:marketTab==='orders'?ordersPage():historicalPage()}`;}
function ordersPage(){const orders=state.orders.filter(o=>!o.historical);return `${!orders.length?'<div class="empty">Todavía no has hecho pedidos. Tu primera compra será una de las decisiones del capítulo 1.</div>':`<div class="grid two">${orders.map(o=>`<div class="card"><span class="tag ${o.delivered===o.qty?'green':''}">${o.delivered===o.qty?'Entregado':o.blocked===state.month?'Pendiente de pago':'Fabricación / homologación'}</span><h3>${MODEL[o.model].name}</h3><p>${o.qty} unidades · ${money(o.total)} contratado</p><div class="progress"><span style="width:${o.delivered/o.qty*100}%"></span></div><div class="split"><span>${o.delivered} / ${o.qty} recibidos</span><span class="small muted">${money(o.remaining)} pendiente</span></div><p style="margin-top:14px">${o.delivered===o.qty?'Pedido cerrado.':`Próximo lote: ${E.dateOf(o.next)}${o.blocked===state.month?' · abona el saldo disponiendo de caja.':''}`}</p>${o.delay?`<p class="negative">Retraso acumulado: ${o.delay} meses.</p>`:''}</div>`).join('')}</div>`}`;}
function historicalPage(){return `<div class="info">Los contratos anteriores a enero de 2022 son heredados. Los posteriores aparecen al llegar a su mes en la campaña. Puedes consultar aquí el registro completo. Las recepciones mensuales son simuladas; los programas de mercancías y C9 se documentan, pero no se explotan en este mapa. Financiación histórica fuera de tu caja de campaña.</div><div class="table-wrap"><table><thead><tr><th>CONTRATO / PROGRAMA</th><th>UNIDADES</th><th>SITUACIÓN EN TU PARTIDA</th><th>TRAZABILIDAD</th></tr></thead><tbody>${HISTORICAL_ORDERS.map(h=>{const o=state.orders.find(x=>x.id===h.id);return `<tr><td><strong>${h.name}</strong><small style="max-width:380px;line-height:1.6">${esc(h.note)}</small></td><td>${h.qty}${h.optional?'<small>+ '+h.optional+' opcionales</small>':''}</td><td>${h.signed>state.month?`<span class="tag">Futuro · ${2022+Math.floor(h.signed/12)}</span>`:h.tender?'<span class="tag">Licitación, no pedido</span>':!h.model?'<span class="tag">Registro documental</span>':`<span class="tag green">${o?.delivered||0} / ${h.qty} simulados</span>`}</td><td class="small">${sourceLink(h.source)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function purchaseDialog(id){const m=MODEL[id];showModal(`<div class="modal-inner">${modalHeader(m.name,'NUEVO PEDIDO')}<p>${m.desc}</p><label for="buyQty">Número de unidades (1–30)</label><input id="buyQty" type="number" min="1" max="30" step="1" value="2"><div id="purchaseQuote"></div><div class="actions"><button class="primary" data-action="confirm-buy" data-id="${id}">Firmar pedido</button><button data-action="close-modal">Cancelar</button></div><p class="small muted" style="margin-top:20px">El plazo incluye ingeniería, fabricación y homologación. Puede acumular de 2 a 6 meses adicionales de retraso. Entregas de hasta 2 unidades por mes.</p></div>`);$('buyQty').dataset.model=id;updateQuote();}
function updateQuote(){try{const id=$('buyQty').dataset.model,q=E.purchaseQuote(state,id,+$('buyQty').value);$('purchaseQuote').innerHTML=`<div class="specs"><div><small>IMPORTE TOTAL</small>${money(q.total)}</div><div><small>ANTICIPO AHORA</small>${money(q.deposit)}</div><div><small>SALDO A LA ENTREGA</small>${money(q.remaining)}</div></div><div class="info">Primer lote estimado: <strong>${E.dateOf(state.month+q.lead)}</strong><br>Último lote previsto: ${E.dateOf(state.month+q.last)} · ${q.lead}–${q.last} meses desde la firma.</div>${state.cash<q.deposit?'<div class="inline-error">No hay caja suficiente para el anticipo.</div>':''}`;}catch(e){$('purchaseQuote').innerHTML=`<p class="inline-error">${esc(e.message)}</p>`;}}
function projectsPage(){return header('Las vías del próximo capítulo.','Negocia con Adif la prioridad y la cofinanciación. El presupuesto representa tu aportación de campaña, no el coste total real de la infraestructura.')+`<div class="toolbar"><button class="primary" data-action="new-line">Proponer una nueva línea</button><span class="small muted">También puedes conectar dos ciudades fuera de los corredores existentes.</span></div><div class="grid two">${PROJECTS.map(p=>{const job=state.projects.find(j=>j.id===p.id),progress=job?job.done?100:Math.max(0,Math.min(99,(state.month-job.started)/(job.due-job.started)*100)):0;return `<article class="card"><div class="split"><span class="eyebrow">${p.region}</span><span class="tag ${job?.done?'green':''}">${job?job.done?'Disponible':'En ejecución':'Negociable'}</span></div><h3>${p.name}</h3><p>${p.desc}</p><div class="info">${p.status}</div>${job?`<div class="progress"><span style="width:${progress}%"></span></div><p>${job.done?'Obra terminada en tu partida.':'Previsión de juego: '+E.dateOf(job.due)+(job.delay?' · +'+job.delay+' meses de retraso':'')}</p>`:`<p>Plazo de juego: ${p.duration} meses; no antes de ${p.earliest}. No es una fecha oficial.</p>`}<div class="card-foot"><strong>${money(p.cost)}</strong><button data-action="project" data-id="${p.id}" ${job||state.ended?'disabled':''}>${job?'Acuerdo firmado':'Financiar proyecto'}</button></div><div class="small" style="margin-top:13px">${sourceLink(p.source)}</div></article>`;}).join('')}</div>${state.projects.some(p=>p.type==='custom')?`<h3 style="margin:26px 0 17px">Tus nuevas líneas</h3><div class="grid two">${state.projects.filter(p=>p.type==='custom').map(p=>`<div class="card"><span class="tag">${p.done?'Disponible':'En construcción'}</span><h3>${esc(E.routeName(state.routes.find(r=>r.id===p.route)))}</h3><p>${p.done?'Ya puedes asignar material.':'Final previsto: '+E.dateOf(p.due)}</p><button class="small" style="margin-top:12px" data-action="route" data-id="${p.route}">Ver en el mapa</button></div>`).join('')}</div>`:''}`;}
function newLineDialog(){showModal(`<div class="modal-inner">${modalHeader('Dibuja el siguiente enlace.','PLANIFICACIÓN DE RED')}<p>Una conexión hipotética entre dos ciudades reales. La distancia incluye un factor de trazado; el mapa dibuja un enlace conceptual, no un proyecto constructivo.</p><div class="form-grid"><div><label for="lineA">Origen</label><select id="lineA">${CITIES.map(c=>`<option value="${c.id}" ${c.id==='mur'?'selected':''}>${c.name}</option>`).join('')}</select></div><div><label for="lineB">Destino</label><select id="lineB">${CITIES.map(c=>`<option value="${c.id}" ${c.id==='vlc'?'selected':''}>${c.name}</option>`).join('')}</select></div></div><label for="lineType">Tipo de infraestructura</label><select id="lineType"><option value="regional">Regional · ancho ibérico · sin electrificar</option><option value="av">Alta velocidad · estándar · electrificada</option></select><div id="lineQuote" class="info"></div><div class="actions"><button class="primary" data-action="confirm-line">Contratar estudio y construcción</button><button data-action="close-modal">Cancelar</button></div></div>`);updateLineQuote();}
function updateLineQuote(){try{const q=E.newLineQuote($('lineA').value,$('lineB').value,$('lineType').value);$('lineQuote').textContent=`${q.km} km estimados · ${money(q.cost)} de aportación · ${q.duration} meses de desarrollo, antes de posibles retrasos.`;}catch(e){$('lineQuote').textContent=e.message;}}
function financePage(){const b=E.balance(state),commit=state.orders.filter(o=>!o.historical).reduce((n,o)=>n+o.remaining,0);return header('Que las cuentas también lleguen.','Cifras en millones de euros de la simulación. El resultado operativo no incluye compras, reformas ni aportaciones a proyectos.')+`<div class="statcards"><div class="card"><small>Tesorería</small><div class="large-number">${n(state.cash,1)}</div><span class="small muted">millones de euros</span></div><div class="card"><small>Resultado mensual previsto</small><div class="large-number ${b.net>=0?'positive':'negative'}">${b.net>=0?'+':''}${n(b.net,1)}</div><span class="small muted">después de costes y ayudas</span></div><div class="card"><small>Deuda pendiente</small><div class="large-number">${n(state.debt,1)}</div><span class="small muted">interés mensual del 0,4%</span></div><div class="card"><small>Compromisos de compra</small><div class="large-number">${n(commit,1)}</div><span class="small muted">saldos pendientes a entrega</span></div></div><div class="grid two"><div class="card"><h3>Cuenta de explotación mensual</h3>${[['Ingresos por billetes',b.revenue],['Apoyo OSP y de campaña',b.subsidy],['Operación, mantenimiento e intereses',-b.cost],['Resultado previsto',b.net]].map(([t,v])=>`<div class="bank-row"><span>${t}</span><strong class="${v>=0?'positive':'negative'}">${signed(v)}</strong></div>`).join('')}<p class="small" style="margin-top:15px">Las ayudas son una abstracción del servicio público. No reproducen la contabilidad real de Renfe.</p></div><div class="card"><h3>Financiación y mantenimiento</h3><div class="actions"><button data-action="borrow" ${state.debt>=1500||state.ended?'disabled':''}>Solicitar 100 M€</button><button data-action="repay" ${state.debt<100||state.cash<100||state.ended?'disabled':''}>Amortizar 100 M€</button></div><label for="maintenance">Esfuerzo de mantenimiento: <strong>${n(state.maintenance*100)}%</strong></label><input id="maintenance" type="range" min="0.6" max="1.5" step="0.1" value="${state.maintenance}" ${state.ended?'disabled':''}><p class="small">Más mantenimiento reduce desgaste y mejora puntualidad; cuesta más. El límite de deuda es 1.500 M€.</p></div></div><div class="card" style="margin-top:18px"><h3>Evolución de tesorería</h3><canvas id="cashChart" class="chart" aria-label="Gráfico de caja mensual" role="img"></canvas><p class="small muted">${state.history.length?'Desde '+E.dateOf(state.history[0].month)+' hasta '+E.dateOf(state.history.at(-1).month):'Avanza el primer mes para ver la evolución.'}</p></div>`;}
function drawChart(){const el=$('cashChart');if(!el)return;const w=el.clientWidth||700,h=170;el.width=w*2;el.height=h*2;const c=el.getContext('2d');c.scale(2,2);const data=state.history.map(h=>h.cash);if(!data.length)return;const min=Math.min(0,...data),max=Math.max(100,...data),y=v=>h-25-(v-min)/(max-min||1)*(h-50);c.font='10px Segoe UI';c.fillStyle='#9eb6a5';c.strokeStyle='#9cb69d22';for(let i=0;i<=3;i++){const val=min+(max-min)/3*i;c.fillText(n(val),5,y(val));c.beginPath();c.moveTo(42,y(val));c.lineTo(w,y(val));c.stroke();}c.strokeStyle='#e8ba76';c.lineWidth=2;c.beginPath();data.forEach((v,i)=>{const x=44+i/(data.length-1||1)*(w-55);i?c.lineTo(x,y(v)):c.moveTo(x,y(v));});c.stroke();}
function archivePage(){return header('El archivo detrás de la historia.','Investigación consultada el 6 de octubre de 2026. Fuentes primarias, contratos y límites de esta primera versión.','HECHOS, PREVISIONES Y FICCIÓN')+`<div class="toolbar"><div class="tabs">${[['sources','Fuentes'],['method','Qué es real'],['journal','Diario de campaña']].map(([id,title])=>`<button data-action="archive-tab" data-value="${id}" class="${archiveTab===id?'active':''}">${title}</button>`).join('')}</div></div>${archiveTab==='journal'?state.log.map(l=>`<article class="news-entry"><time>${E.dateOf(l.month)}</time><div><h3>${esc(l.title)}</h3><p>${esc(l.body)}</p></div></article>`).join(''):archiveTab==='method'?`<div class="methodology"><h3>Una historia alternativa, no una reconstrucción documental</h3><ul><li><strong>Premisa ficticia:</strong> venta masiva de flota y suspensión inicial de numerosos servicios. No ocurrió así en la Renfe real de 2022. La escasez de material y los retrasos del S106 sí están documentados.</li><li><strong>Geografía:</strong> contornos reales de España y Portugal, vías OpenStreetMap y estaciones georreferenciadas. Hay 114 recorridos calculados sobre vías existentes de una instantánea de abril de 2026; no son itinerarios certificados. Los cinco recorridos sin continuidad no se rellenan con rectas. Las líneas nuevas del jugador son proyectos conceptuales.</li><li><strong>Red:</strong> 56 corredores estratégicos,15 núcleos y 63 líneas o ramales de Cercanías disponibles para planificar, diez programas de infraestructura y enlaces creados por el jugador. No es toda la RFIG. Las estaciones se basan en 1.494 registros oficiales con fecha conservada; sus etiquetas no certifican servicio actual.</li><li><strong>Contratos:</strong> registro de los principales programas identificados. Opciones y licitaciones se distinguen de adjudicaciones. No se certifica la exhaustividad de todas las compras, modificaciones, vagones o pedidos de filiales.</li><li><strong>Calendarios:</strong> la campaña usa días operativos y una liquidación mensual. C5 de Bilbao se desbloquea el 06-05-2026. Las muestras documentales son 42 circulaciones o salidas publicadas de Cádiz, Sevilla y Bilbao con la vigencia indicada; donde no hay hora de llegada, queda desconocida. Los GTFS completos cargados aportan calendario, excepciones, paradas, horarios y shapes. Los horarios actuales no reconstruyen 2022. Entregas y finales de obra del juego se simulan. Los periodos de financiación europea no se usan como fechas garantizadas de inauguración.</li><li><strong>Precios y economía:</strong> cifras ficticias para jugabilidad, no presupuestos reales. La financiación de contratos históricos va fuera de tu caja. El coste de negociar una obra es una aportación de campaña, no el coste integral de Adif.</li><li><strong>Flota:</strong> las compras nuevas incluyen reediciones hipotéticas. Capacidades, longitudes, señalización, gálibos y tensiones están simplificados. Sí se comprueban ancho, electrificación, disponibilidad y tiempo de entrega.</li><li><strong>Competencia:</strong> Alsa reacciona con promociones simuladas. Ouigo e iryo presionan en alta velocidad. Las cuotas son del modelo, no cifras oficiales.</li><li><strong>Después de 2026:</strong> desarrollo contrafactual hasta 2050. No se predicen gobiernos, contratos ni aperturas reales.</li><li><strong>Personajes:</strong> Pedro Sancho, Raquel Sanz y Óscar del Puente son caricaturas originales con nombres y diálogos inventados. No son declaraciones de políticos reales.</li></ul><h3>Cómo se calcula una partida</h3><p>El atractivo combina tiempo, tarifa, frecuencia y fiabilidad. La demanda se reparte entre Renfe, autobús y otros modos. La capacidad limita los pasajeros. Los ingresos son viajeros por tarifa; se descuentan tren-km, energía, mantenimiento y deuda. Las obras y entregas pueden sufrir un único retraso acotado por expediente. El cierre de 2050 valora cobertura, satisfacción, caja neta y capítulos.</p><div class="info">Versión estratégica por jornadas. Los gráficos son un mapa 2D con vías OSM, trenes por horario y luz estacional; no hay un mundo 3D al nivel de un juego comercial como Tropico. El contenido documental está congelado a la fecha de investigación. El atlas distingue series y variantes de unidades físicas: el GTFS no informa de matrícula o serie asignada a cada circulación.</div><h3>Créditos de cartografía</h3><p>España y Portugal: georgique/world-geojson, GPL-3.0. Selección y empaquetado del 6 de octubre de 2026, sin alterar coordenadas. Los datos en su formato editable y la licencia íntegra acompañan al proyecto. Vías: © OpenStreetMap contributors, ODbL-1.0; geometrías simplificadas a 18 m y rutas calculadas. Fuente, datos editables, manifiesto y licencia acompañan al proyecto. Consulta https://www.openstreetmap.org/copyright. Estaciones y fichas: RenfeData, CC BY 4.0, con fecha y fuente por registro. Otros contornos: Natural Earth / johan/world.geo.json, dominio público. Las marcas identifican a los operadores; este juego no es un producto oficial de Renfe.</p><button data-action="license" style="margin-top:18px">Licencia de los datos cartográficos</button></div>`:`<div class="info">${SOURCES.length} referencias. Los enlaces permiten comprobar cada afirmación. Una nota de prensa expresa una situación o una previsión en su fecha; no demuestra que todo lo anunciado ya esté terminado.</div><div class="source-list">${SOURCES.map(s=>`<article class="card"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a><p>${esc(s.note)}</p></article>`).join('')}</div>`}`;}
function parseClock(t){const [h,m]=t.split(':').map(Number);return h*60+m;}
function renderClock(){$('dayDock').classList.toggle('reference',observing);if(observing){$('dayDock').innerHTML=`<div class="clock-face"><span>◷</span><strong>${O.clockText(referenceMinute)}</strong><small>Horario real</small></div><div class="day-track"><strong>Fecha de referencia: ${esc(referenceDate)}</strong><label for="mapReferenceClock">Hora del horario publicado</label><input id="mapReferenceClock" type="range" min="0" max="${referenceEndMinute()}" step="1" value="${referenceMinute}"></div><button data-action="leave-reference">Volver a la campaña</button>`;return;}const op=O.ensureOps(state),bounds=O.dayBounds(dayTrips),minute=op.phase==='planning'?bounds.first:op.minute,live=op.phase==='running'?dayTrips.filter(t=>minute>=t.dep&&minute<t.arrival).length:0,light=O.daylight(state,minute);$('dayDock').innerHTML=`<div class="clock-face"><span>${light.night>.5?'☾':'☀'}</span><strong>${O.clockText(minute)}</strong><small>${op.phase==='planning'?'Preparación':op.phase==='running'?'Jornada en curso':'Jornada cerrada'}</small></div><div class="day-track"><div class="split"><span>Primera salida ${O.clockText(bounds.first)}</span><span>Última llegada ${O.clockText(bounds.last)}</span></div><div class="progress"><span style="width:${op.phase==='planning'?0:Math.max(0,(minute-bounds.first)/(bounds.last-bounds.first||1)*100)}%"></span></div><small>${live} trenes en circulación · ${dayTrips.length} salidas programadas</small></div><div class="dock-actions"><button data-action="navigate" data-screen="operations">Tablero del día</button><button class="primary" data-action="${op.phase==='review'?'day-review':op.phase==='planning'?'day-start':'day-end'}">${op.phase==='review'?'Ver cierre':op.phase==='planning'?'Comenzar jornada':'Hasta el último tren'}</button></div>`;const pending=op.incidents.find(x=>op.minute>=x.at&&!op.resolved.includes(x.trip));if(pending)$('tickerText').textContent=pending.reason+' · '+E.routeName(state.routes.find(r=>r.id===pending.route))+' · atiéndela en Circulación del día.';}
function operationsPage(){const op=O.ensureOps(state),bounds=O.dayBounds(dayTrips),minute=op.phase==='planning'?bounds.first:op.minute,upcoming=dayTrips.filter(t=>t.arrival>=minute).slice(0,75),incidents=op.incidents.filter(x=>op.minute>=x.at);return header('El próximo tren está en tus manos.',O.dayLabel(state)+' · Plan de campaña simulado. Los horarios oficiales tienen su propia fecha en Horarios reales.','CENTRO DE CONTROL')+`<div class="operating-strip"><div><small>RELOJ DE JORNADA</small><strong>${O.clockText(minute)}</strong></div><div><small>EN CIRCULACIÓN</small><strong>${dayTrips.filter(t=>minute>=t.dep&&minute<t.arrival).length}</strong></div><div><small>ÚLTIMA LLEGADA</small><strong>${O.clockText(bounds.last)}</strong></div><div class="actions"><button class="primary" data-action="${op.phase==='review'?'day-review':'day-start'}">${op.phase==='review'?'Revisar jornada':op.phase==='running'?'Reanudar':'Despachar primer tren'}</button>${op.phase==='running'?'<button data-action="day-end">Hasta el último tren</button>':''}</div></div><div class="operating-priority"><label for="dayPriority">Prioridad de explotación</label><select id="dayPriority" ${op.phase!=='planning'?'disabled':''}><option value="balanced" ${op.priority==='balanced'?'selected':''}>Equilibrio entre coste y puntualidad</option><option value="punctual" ${op.priority==='punctual'?'selected':''}>Refuerzo de puntualidad · 9.000 €/día</option></select><p class="small">El refuerzo reduce 5 minutos de retraso por circulación. Los equipos de incidencia cuestan 18.000 € y reducen la demora al 25%.</p></div>${incidents.length?`<div class="incident-list">${incidents.map(i=>`<div><span class="tag red">${op.resolved.includes(i.trip)?'Equipo movilizado':'Atención requerida'}</span><h3>${esc(i.reason)}</h3><p>${esc(E.routeName(state.routes.find(r=>r.id===i.route)))} · demora inicial ${i.delay} min</p><button data-action="resolve-incident" data-id="${i.trip}" ${op.resolved.includes(i.trip)||op.phase!=='running'?'disabled':''}>Movilizar equipo · 18.000 €</button></div>`).join('')}</div>`:''}<div class="table-wrap"><table><thead><tr><th>SALIDA</th><th>CIRCULACIÓN</th><th>MATERIAL</th><th>LLEGADA</th><th>SITUACIÓN</th></tr></thead><tbody>${upcoming.map(t=>`<tr><td class="mono">${O.clockText(t.dep)}</td><td><button class="text-button" data-action="route" data-id="${t.route}">${CITY[t.ends[0]].name} — ${CITY[t.ends[1]].name}</button><small>ID de simulación ${esc(t.id)}</small></td><td>${esc(t.model)}</td><td class="mono">${O.clockText(t.arrival)}</td><td>${minute<t.dep?'Preparado':minute<t.arrival?'En marcha':'Llegada'}${t.delay?`<small class="negative">+${t.delay} min</small>`:''}</td></tr>`).join('')}</tbody></table></div>${!dayTrips.length?'<div class="empty">Asigna material a un servicio para comenzar a circular.</div>':''}<p class="small muted">Las llegadas se calculan con distancia, velocidad comercial y restricciones de obra. Los cierres diarios muestran una estimación; las cuentas de explotación se liquidan al final del mes, y las intervenciones se pagan al instante. Puedes delegar meses desde la barra superior para completar el mandato hasta 2050.</p>`;}
function dayReview(){const last=state.ops.last;if(!last)return;showModal(`<div class="modal-inner">${modalHeader('El último tren ha llegado.','CIERRE DE JORNADA')}<p>${esc(last.date)}</p><div class="operating-strip"><div><small>SALIDAS</small><strong>${last.trains}</strong></div><div><small>PUNTUALIDAD</small><strong>${last.punctuality}%</strong></div><div><small>VIAJEROS ESTIMADOS</small><strong>${num(last.passengers)}</strong></div></div><div class="bank-row"><span>Primera salida / última llegada</span><strong>${O.clockText(last.first)} / ${O.clockText(last.last)}</strong></div><div class="bank-row"><span>Incidencias atendidas</span><strong>${last.attended} / ${last.incidents}</strong></div><div class="bank-row"><span>Resultado diario estimado</span><strong>${money(last.net)}</strong></div><p class="small" style="margin-top:20px">La explotación se liquida una vez al cerrar el mes. Este resumen distribuye la previsión mensual entre sus días; no añade un segundo ingreso.</p><div class="actions"><button class="primary" data-action="day-next">Preparar la siguiente jornada</button><button data-action="close-modal">Volver al tablero</button></div></div>`);}
function cercaniasPage(){const network=COMMUTER_NETWORKS.find(x=>x.id===networkId)||COMMUTER_NETWORKS[0],matches=stationQuery?REAL_STATIONS.filter(s=>(s.name+' '+s.province+' '+s.town).toLowerCase().includes(stationQuery.toLowerCase())).slice(0,80):[];return header('Cada núcleo, su propia red.','Inventario documental de líneas contrastado en octubre de 2026. Sus cambios posteriores a2022 se indican en la ficha.','CERCANÍAS · RODALIES · ANCHO MÉTRICO')+`<div class="network-nav">${COMMUTER_NETWORKS.map(x=>`<button data-action="network" data-id="${x.id}" class="${network?.id===x.id?'active':''}">${esc(x.name)}</button>`).join('')}</div>${network?`<div class="network-heading"><h2>${esc(network.name)}</h2><button data-action="network-map" data-id="${network.id}">Acercar a este núcleo</button></div><p class="small muted">${esc(network.note||'Los horarios dependen del calendario, obras y excepciones. La existencia de la línea no garantiza que toda su oferta sea idéntica en 2022.')}</p><div class="line-list">${network.lines.map((line,i)=>`<div><span class="line-code">${esc(line.code)}</span><div><h3>${esc(line.name||line.from+' — '+line.to)}</h3><p>${esc(line.note||'')}</p></div><button data-action="commuter-plan" data-id="${network.id}:${i}">Preparar servicio</button></div>`).join('')}</div><p class="small">${network.source?`<a href="${esc(network.source)}" target="_blank" rel="noopener noreferrer">Mapa oficial del núcleo</a>`:''}</p>`:''}<hr class="divider"><div class="split"><div><h3>Estaciones oficiales</h3><p class="small muted">${REAL_STATIONS.length} registros georreferenciados · Renfe Data · CC BY 4.0</p></div><input id="stationSearch" placeholder="Buscar estación o provincia" value="${esc(stationQuery)}" aria-label="Buscar estación"></div>${stationQuery?`<div class="table-wrap"><table><thead><tr><th>ESTACIÓN</th><th>LOCALIDAD</th><th>RED</th><th></th></tr></thead><tbody>${matches.map(s=>`<tr><td><strong>${esc(s.name)}</strong><small>${s.id}</small></td><td>${esc(s.town)}<small>${esc(s.province)}</small></td><td>${s.commuter?'Cercanías ':''}${s.metric?'Ancho métrico':''}</td><td><button data-action="station-map" data-id="${s.id}">Ver estación</button></td></tr>`).join('')}</tbody></table></div>`:''}<p class="small muted">El catálogo de estaciones combina registros2026 con suplementos oficiales2019/2021 y conserva su fecha. Sus banderas administrativas no acredita por sí solo que una parada tenga servicio hoy. Las líneas se planifican con trenes de tu parque; su demanda, tiempos y tarifas siguen siendo simulación.</p>`;}
function commuterPlan(key){try{const [id,index]=key.split(':'),network=COMMUTER_NETWORKS.find(x=>x.id===id),line=network.lines[+index],rid='c-'+id+'-'+line.code.toLowerCase().replace(/[^a-z0-9]/g,'');const existing=state.routes.find(r=>r.id===rid);if(existing)return selectRoute(rid);const normalize=x=>String(x).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');const find=(value,stationId)=>REAL_STATIONS.find(s=>s.id===stationId)||REAL_STATIONS.find(s=>normalize(s.name)===normalize(value))||REAL_STATIONS.find(s=>normalize(s.name).includes(normalize(value))&&normalize(value).length>4);const a=find(line.from,line.fromStation),b=find(line.to,line.toStation);if(!a||!b)throw Error('Los extremos de esta línea necesitan verificarse en un GTFS. Consulta su mapa oficial e importa el horario para observarla.');if(a.id===b.id&&!line.circular)throw Error('La línea necesita extremos distintos y un recorrido de paradas verificado.');E.ensurePlaying(state);const lat=(a.lat+b.lat)/2*Math.PI/180,km=RAIL_PATHS[rid]?.lengthKm?Math.round(RAIL_PATHS[rid].lengthKm):Math.round(Math.hypot((a.lon-b.lon)*111*Math.cos(lat),(a.lat-b.lat)*111)*1.3);state.routes.push({id:rid,name:network.name+' '+line.code,ends:['st'+a.id,'st'+b.id],via:['st'+a.id,...(line.viaStationIds||[]).map(x=>'st'+x),'st'+b.id],circular:!!line.circular,km:Math.max(3,km),gauge:line.metric?'metric':'iberian',power:line.diesel?'diesel':'electric',speed:line.metric?70:100,demand:line.metric?18000:85000,fare:3,active:false,kind:'commuter',availableFrom:line.activationDate||null,unlock:line.activationDate?Math.max(0,(Number(line.activationDate.slice(0,4))-2022)*12+Number(line.activationDate.slice(5,7))-1):line.since?Math.max(0,(line.since-2022)*12):0,project:null,level:0,frequency:8,units:0,fleet:null,commuter:true});autosave();selectRoute(rid);toast('Línea preparada. Asigna material y confirma el plan de servicio.');}catch(e){toast(e.message);}}
function realSchedule(){if(referenceCacheFeed===referenceFeed&&referenceCacheDate===referenceDate)return referenceCacheTrips;referenceCacheFeed=referenceFeed;referenceCacheDate=referenceDate;if(referenceFeed)return referenceCacheTrips=G.scheduleFor(referenceFeed,referenceDate);const day=new Date(referenceDate+'T12:00:00Z').getUTCDay();return referenceCacheTrips=REAL_DEPARTURES.filter(t=>(!t.weekdays||t.weekdays.includes(day))&&referenceDate>=t.validFrom&&(!t.validTo||referenceDate<=t.validTo)).map(t=>({...t,real:true,delay:0,model:t.model||'Material no acreditado para esta circulación',coords:t.coords||[],duration:t.arrival===null?0:t.arrival-t.dep,scheduled:t.arrival}));}
function timetablesPage(){if(!referenceDate)referenceDate='2022-10-26';referenceTrips=realSchedule();let rows=referenceTrips.filter(t=>(!referenceRoute||t.route===referenceRoute)&&(!referenceSearch||(t.name+' '+t.id+' '+t.headsign).toLowerCase().includes(referenceSearch.toLowerCase())));referenceViewTrips=rows;const routes=[...new Map(referenceTrips.map(t=>[t.route,{id:t.route,name:t.name}])).values()];return header('Un horario tiene fecha.','Consulta circulaciones, calendarios y paradas del archivo importado. El GTFS no identifica la matrícula ni garantiza una serie concreta.','DATOS REALES · FECHA DE REFERENCIA')+`<div class="real-feed-strip"><div><strong>${referenceFeed?esc(referenceFeed.name):'Muestra documental: Cádiz C1a, Sevilla C4 y Bilbao C5'}</strong><p>${referenceFeed?Object.keys(referenceFeed.routes).length+' variantes de ruta · '+Object.keys(referenceFeed.trips).length+' viajes en el archivo':REAL_DEPARTURES.length+' salidas publicadas por Renfe. Cádiz y Sevilla tienen llegadas publicadas; Bilbao2026 solo salidas acreditadas.'}</p></div><div><label for="gtfsImport">Cargar horario completo (.zip)</label><input id="gtfsImport" type="file" accept=".zip,application/zip"><span id="gtfsProgress" role="status" class="small"></span></div></div><div class="feed-links">${G.GTFS_LINKS.map(l=>`<a href="${l.url}" target="_blank" rel="noopener noreferrer">Descargar GTFS ${l.name}</a>`).join('')}</div><p class="small muted">Los ZIP completos de Renfe no pudieron descargarse en esta sesión. Puedes cargarlos aquí: se leen localmente, incluyendo calendario, excepciones, horas después de medianoche y shapes reales si existen. Una actualización2026 no se presenta como horario histórico2022.</p><div class="toolbar"><div><label for="referenceDate">Día del horario</label><input id="referenceDate" type="date" value="${referenceDate}" ${referenceFeed?'min="'+G.dateISO(referenceFeed.dateStart)+'" max="'+G.dateISO(referenceFeed.dateEnd)+'"':''}></div><div><label for="referenceRoute">Línea</label><select id="referenceRoute"><option value="">Todas las circulaciones</option>${routes.map(r=>`<option value="${esc(r.id)}" ${referenceRoute===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><input id="referenceSearch" aria-label="Buscar tren del horario" placeholder="Línea, destino o ID de viaje" value="${esc(referenceSearch)}"><button data-action="reference-map" ${!rows.some(t=>t.arrival!==null&&t.coords.length)?'disabled':''}>Observar en el mapa</button></div><div class="reference-clock"><label for="referenceClock">Hora de observación: <strong>${O.clockText(referenceMinute)}</strong></label><input id="referenceClock" type="range" min="0" max="${referenceEndMinute()}" step="1" value="${referenceMinute}"></div><p class="small">${num(rows.length)} circulaciones en la fecha elegida. ${referenceFeed?Object.keys(referenceFeed.shapes).length+' trazados shapes del archivo.':'Consulta la validez y las condiciones de la muestra en cada tren.'}</p><div class="table-wrap"><table><thead><tr><th>SALIDA</th><th>TREN / LÍNEA</th><th>DESTINO</th><th>LLEGADA</th><th></th></tr></thead><tbody>${rows.slice(0,150).map(t=>`<tr><td class="mono">${t.approximate?'Cada '+n(t.frequency.headway)+' min':O.clockText(t.dep)}</td><td><strong>${esc(t.name)}</strong><small>${esc(t.id)}</small></td><td>${esc(t.headsign||t.stops?.at(-1)?.name||'')}</td><td class="mono">${t.arrival===null?'No publicada':O.clockText(t.arrival)}</td><td><button data-action="real-trip" data-id="${esc(t.id)}">Ver paradas</button></td></tr>`).join('')}</tbody></table></div>${rows.length>150?'<p class="small">Se muestran150 resultados. Filtra por línea o ID para consultar otro tren.</p>':''}${!rows.length?'<div class="empty">No hay circulaciones acreditadas en esta fecha dentro de los datos cargados.</div>':''}`;}
function referenceEndMinute(){return Math.max(1440,Math.ceil(referenceTrips.reduce((v,t)=>Math.max(v,t.arrival??t.dep),0)/60)*60);}
function realTripDetail(id){const t=referenceTrips.find(t=>t.id===id);if(!t)return;showModal(`<div class="modal-inner">${modalHeader(t.name,'CIRCULACIÓN PUBLICADA')}<p>ID de viaje: ${esc(t.id)} · ${referenceDate}</p><p class="small">${esc(t.model)}. ${esc(t.note||'El ID del viaje no es la matrícula de un vehículo físico. La posición animada entre paradas es una interpolación visual.')}</p><div class="stop-list">${(t.times||[]).map((v,i)=>{const stop=t.stops?.[i];return `<div><span class="mono">${v[2]===null?'Sin hora publicada':O.clockText(v[2])}</span><strong>${esc(stop?.name||v[1])}</strong><span class="small">${t.publishedOnly?'Hora de parada publicada':v[3]===null?'Salida no publicada':'Salida '+O.clockText(v[3])}</span></div>`;}).join('')||'<p>Solo se dispone de la salida publicada; no se han inventado horas de llegada.</p>'}</div>${t.source?`<a href="${esc(t.source)}" target="_blank" rel="noopener noreferrer">Fuente y condiciones del horario</a>`:''}</div>`);}
function trainsPage(){const records=REAL_TRAIN_CATALOGUE.filter(t=>!trainQuery||[t.series,t.name,t.category,t.maker].join(' ').toLowerCase().includes(trainQuery.toLowerCase()));return header('Los trenes, con nombre y ficha.','Series, variantes y programas documentados. Una serie no equivale a una matrícula ni a una asignación diaria.','ATLAS DE MATERIAL RODANTE')+`<div class="train-atlas-image" role="img" aria-label="Ilustración de un tren español al atardecer"></div><div class="toolbar"><input id="trainSearch" placeholder="Buscar serie, fabricante o familia" value="${esc(trainQuery)}" aria-label="Buscar serie real"><span class="small">${records.length} registros documentales</span></div><div class="train-list">${records.map((t,i)=>`<button data-action="train-record" data-id="${t.id}"><span class="train-series">${esc(t.series||t.name)}</span><div><strong>${esc(t.name||t.series)}</strong><p>${esc(t.category||t.service||'Ficha de material')} · ${esc(t.maker||'')}</p></div><span>${t.speed!==null&&t.speed!==undefined?t.speed+'km/h':'Consultar ficha'}</span></button>`).join('')}</div><p class="small muted">La base técnica RenfeData de abril de 2020 se conserva con su fecha y discrepancias, y se amplía con fuentes de 2021–2026. No es un censo de unidades activas. Los precios y la disponibilidad del catálogo de compras son parámetros del juego.</p>`;}
function trainRecord(id){const t=REAL_TRAIN_CATALOGUE.find(x=>x.id===id);if(!t)return;const fields=[['Velocidad máxima',t.speed?`${t.speed} km/h`:null],['Ancho',t.gauge],['Tracción',t.traction||t.power],['Plazas sentadas',t.seated||t.seats],['Capacidad total',t.totalCapacity||t.capacity],['Construidas (fuente)',t.built],['Pedido / contrato',t.contracted??t.firmOrderUnits],['Estado documental',t.status]];showModal(`<div class="modal-inner">${modalHeader(t.name||t.series,'FICHA DE SERIE')}<div class="train-series">${esc(t.series)}</div>${fields.map(([name,v])=>`<div class="bank-row"><span>${name}</span><strong>${v!==null&&v!==undefined?esc(typeof v==='object'?JSON.stringify(v):v):'No verificado'}</strong></div>`).join('')}<p style="margin:20px 0">${esc(t.note||t.notes||'')}</p><div class="methodology">${(t.warnings||[]).map(x=>'<p>'+esc(x)+'</p>').join('')}</div>${(t.sources||[]).map(s=>typeof s==='string'?`<a href="${esc(s)}" target="_blank" rel="noopener noreferrer">Fuente de la ficha</a>`:`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title||'Fuente de la ficha')}</a>`).join('<br>')}</div>`);}
document.addEventListener('change',async event=>{const t=event.target;if(t.id==='dayPriority'){if(state.ops.phase==='planning'){state.ops.priority=t.value;autosave();render();}}if(t.id==='referenceDate'||t.id==='referenceRoute'){if(t.id==='referenceDate')referenceDate=t.value;else referenceRoute=t.value;referenceTrips=realSchedule();renderPanel();}if(t.id==='gtfsImport'&&t.files[0]){const input=t,file=t.files[0];input.disabled=true;try{pause();const feed=await G.importGTFS(file,message=>{const el=$('gtfsProgress');if(el)el.textContent=message;});referenceFeed=G.combineFeeds(referenceFeed,feed);referenceDate=G.dateISO(feed.dateStart);referenceRoute='';referenceTrips=realSchedule();try{await G.storeFeed(referenceFeed);toast('Horario completo cargado y conservado en este navegador.');}catch{toast('Horario cargado. El navegador no pudo conservarlo; mantén el ZIP para volver a importarlo.');}if(screen==='timetables')renderPanel();}catch(e){toast('No se pudo leer el horario: '+e.message);const el=$('gtfsProgress');if(el)el.textContent=e.message;input.disabled=false;}}});
document.addEventListener('input',event=>{const t=event.target;const queries={stationSearch:'station',trainSearch:'train',referenceSearch:'reference'};if(queries[t.id]){if(t.id==='stationSearch')stationQuery=t.value;if(t.id==='trainSearch')trainQuery=t.value;if(t.id==='referenceSearch')referenceSearch=t.value;const id=t.id,pos=t.selectionStart;renderPanel();$(id)?.focus();$(id)?.setSelectionRange(pos,pos);}if(t.id==='mapReferenceClock'){referenceMinute=+t.value;$('dayDock').querySelector('.clock-face strong').textContent=O.clockText(referenceMinute);}if(t.id==='referenceClock'){referenceMinute=+t.value;t.previousElementSibling.innerHTML='Hora de observación: <strong>'+O.clockText(referenceMinute)+'</strong>';}});

function saveDialog(){showModal(`<div class="modal-inner">${modalHeader('Tu partida, a salvo.','GUARDADO LOCAL')}<p>El guardado automático pertenece a este navegador y dispositivo. Exporta una copia para conservarla o continuar en otro equipo.</p><div class="actions"><button class="primary" data-action="save-now">Guardar ahora</button><button data-action="export">Exportar partida (.json)</button></div><hr class="divider"><label for="importSave">Importar una partida</label><input id="importSave" type="file" accept="application/json,.json"><p class="small muted" style="margin-top:14px">Importar sustituye la partida abierta después de validar el archivo.</p></div>`);}
function help(){showModal(`<div class="modal-inner">${modalHeader('Primero, que vuelvan los trenes.','CÓMO JUGAR')}<div class="methodology"><ol><li>Abre <strong>Red y servicios</strong>. Elige un corredor recuperable, asigna material compatible y pulsa Reabrir. Empiezas con trenes libres.</li><li>En <strong>Flota y talleres</strong>, reforma dos unidades libres. Tardarán cinco meses.</li><li>En <strong>Comprar trenes</strong>, encarga al menos dos unidades. Pagas el 30% ahora y el resto cuando lleguen.</li><li>Inicia una jornada con <strong>Comenzar jornada</strong>; prepara servicios, observa trenes y atiende incidencias hasta la última llegada. Puedes delegar el mes con <strong>Delegar mes</strong> o ▶. Cambia entre 1×, 3× y 8×. Las decisiones interrumpen el tiempo.</li><li>Completa los objetivos del <strong>Modo historia</strong> y reclama la financiación de cada etapa.</li><li>Negocia obras y crea nuevas conexiones en <strong>Infraestructura</strong>. Después tendrás que asignarles trenes.</li></ol><p><span class="key">Espacio</span> pausa o reanuda · <span class="key">Esc</span> cierra paneles · rueda para ampliar · arrastra el mapa para moverte.</p><div class="info">Abre servicios cortos con frecuencias moderadas. Más trenes no siempre significan más beneficio. Si falta caja para una entrega, puedes solicitar financiación. La partida se guarda localmente.</div></div></div>`);}
function exportSave(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Iberia-Ferroviaria-'+E.yearOf(state)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Partida exportada.');}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;switch(a){
 case 'navigate':navigate(b.dataset.screen);break;case 'close-modal':closeModal();break;case 'begin':state=E.initialState();O.ensureOps(state);state.started=true;closeModal();render();autosave();showDecision();break;case 'continue':if(saved){state=E.validateSave(saved);state.started=true;closeModal();render();if(E.pendingDecision(state))showDecision();}break;
 case 'decision':if(act(()=>E.decide(state,id,+b.dataset.choice))){closeModal();if(E.pendingDecision(state))showDecision();}break;case 'claim':act(()=>E.claimChapter(state),'Financiación recibida. Tu siguiente etapa está preparada.');break;
 case 'leave-reference':observing=false;render();break;case 'day-start':resume();break;case 'day-next':O.nextDay(state);closeModal();autosave();render();if(E.pendingDecision(state))showDecision();break;case 'day-review':dayReview();break;case 'day-end':pause();if(state.ops.phase==='running'){state.ops.minute=O.dayBounds(O.servicePlan(state)).last;O.endDay(state);autosave();render();dayReview();}break;case 'resolve-incident':act(()=>O.resolveIncident(state,id),'Equipo movilizado. Se reduce el retraso.');break;case 'network':networkId=id;renderPanel();break;case 'network-map':{const area=COMMUTER_NETWORKS.find(x=>x.id===id);navigate('map');map.focusAt(area.lon,area.lat,10);break;}case 'station-map':{const st=REAL_STATIONS.find(x=>x.id===id);navigate('map');map.focusAt(st.lon,st.lat,22);break;}case 'commuter-plan':commuterPlan(id);break;case 'real-trip':realTripDetail(id);break;case 'reference-map':observing=true;navigate('map');observing=true;toast('Observación del horario '+referenceDate+'. No modifica la campaña de 2022.');break;case 'train-record':trainRecord(id);break;case 'route':selectRoute(id);break;case 'close-route':selected=null;map.selected=null;render();break;case 'route-filter':routeFilter=b.dataset.value;renderPanel();break;
 case 'close-service':act(()=>E.closeRoute(state,id),'Servicio suspendido. El material queda libre.');break;case 'upgrade':act(()=>E.upgradeRoute(state,id),'Mejora contratada. Termina en cuatro meses.');break;
 case 'fleet-tab':fleetTab=b.dataset.value;renderPanel();break;case 'fleet-detail':fleetDetail(id);break;case 'refurbish':if(act(()=>E.refurbish(state,id,+$('fleetQty').value),'Material enviado a reforma.'))closeModal();break;case 'sell':if(act(()=>E.sell(state,id,+$('fleetQty').value),'Venta completada.'))closeModal();break;
 case 'market-tab':marketTab=b.dataset.value;renderPanel();break;case 'purchase':purchaseDialog(id);break;case 'confirm-buy':if(act(()=>E.buy(state,id,+$('buyQty').value),'Pedido firmado. Consulta su avance en Mis pedidos.'))closeModal();break;
 case 'project':showModal(`<div class="modal-inner">${modalHeader(PROJECTS.find(p=>p.id===id).name,'ACUERDO DE INFRAESTRUCTURA')}<p>Aportación de campaña: <strong>${money(PROJECTS.find(p=>p.id===id).cost)}</strong>. Se carga al firmar. La obra seguirá su calendario con posibilidad de retraso.</p><div class="actions"><button class="primary" data-action="confirm-project" data-id="${id}">Firmar y financiar</button><button data-action="close-modal">Cancelar</button></div></div>`);break;case 'confirm-project':if(act(()=>E.startProject(state,id),'Acuerdo con Adif firmado.'))closeModal();break;
 case 'new-line':newLineDialog();break;case 'confirm-line':if(act(()=>E.buildLine(state,$('lineA').value,$('lineB').value,$('lineType').value),'Nueva conexión en desarrollo.'))closeModal();break;
 case 'borrow':act(()=>E.loan(state,100),'Financiación de 100 M€ recibida.');break;case 'repay':act(()=>E.loan(state,-100),'100 M€ de deuda amortizados.');break;case 'archive-tab':archiveTab=b.dataset.value;renderPanel();break;
 case 'license':showModal('<div class="modal-inner">'+modalHeader('Licencia de cartografía')+'<pre style="white-space:pre-wrap;font-size:12px;line-height:1.6">'+esc(document.getElementById('geodata-license')?.textContent||'Consulta LICENSE-GEODATA.txt incluido en el proyecto editable. https://github.com/georgique/world-geojson/blob/develop/LICENSE')+'</pre></div>');break;case 'save-dialog':saveDialog();break;case 'save-now':autosave(true);break;case 'export':exportSave();break;case 'new-game':showModal(`<div class="modal-inner">${modalHeader('¿Un nuevo mandato?')}<p>La nueva campaña sustituirá el guardado automático. Exporta la actual si quieres conservarla.</p><div class="actions"><button data-action="export">Exportar actual</button><button class="primary" data-action="begin">Empezar en 2022</button><button data-action="close-modal">Cancelar</button></div></div>`);break;
 }});
document.addEventListener('submit',event=>{if(event.target.id==='routeForm'){event.preventDefault();act(()=>E.configureRoute(state,selected,$('routeFleet').value,+$('frequency').value,+$('fare').value,parseClock($('firstDeparture').value),parseClock($('lastDeparture').value)),'Plan de servicio actualizado.');}});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='routeSearch'){filter=t.value;const pos=t.selectionStart;renderPanel();$('routeSearch').focus();$('routeSearch').setSelectionRange(pos,pos);}if(['routeFleet','frequency','fare','firstDeparture','lastDeparture'].includes(t.id))updateRoutePreview();if(t.id==='buyQty')updateQuote();if(['lineA','lineB','lineType'].includes(t.id))updateLineQuote();});
document.addEventListener('change',async event=>{const t=event.target;if(t.id==='maintenance')act(()=>{E.ensurePlaying(state);state.maintenance=E.clamp(+t.value,.6,1.5);});if(t.id==='importSave'&&t.files[0]){try{if(t.files[0].size>3e6)throw Error('El archivo es demasiado grande.');const candidate=E.validateSave(JSON.parse(await t.files[0].text()));state=candidate;O.ensureOps(state);state.started=true;autosave();closeModal();selected=null;screen='map';render();toast('Partida importada.');if(E.pendingDecision(state))showDecision();}catch(e){toast('No se pudo importar: '+e.message);}}});
$('pause').onclick=()=>playing?pause():resume();$('nextMonth').onclick=()=>{pause();try{if(O.skipMonth(state)){autosave();render();if(E.pendingDecision(state))showDecision();if(state.ended)navigate('story');}}catch(e){toast(e.message);}};document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>setSpeed(+b.dataset.speed));$('zoomIn').onclick=()=>map.zoomAt(map.zoom*1.4);$('zoomOut').onclick=()=>map.zoomAt(map.zoom/1.4);$('resetMap').onclick=()=>map.reset();document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{map.layer=b.dataset.layer;map.dirty=true;document.querySelectorAll('[data-layer]').forEach(x=>x.classList.toggle('active',x===b));if(map.layer==='competition')toast('Alsa compite por precio y flexibilidad. Selecciona un corredor para comparar las cuotas simuladas.');});$('saveButton').onclick=saveDialog;$('helpButton').onclick=help;$('newsButton').onclick=()=>{archiveTab='journal';navigate('archive');};
document.addEventListener('keydown',event=>{if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName))return;if(event.code==='Space'&&!$('modal').open){event.preventDefault();playing?pause():resume();}if(event.key==='Escape'&&!$('modal').open){selected=null;screen='map';render();}});
$('modal').addEventListener('cancel',event=>{if(E.pendingDecision(state)||!state.started)event.preventDefault();});
function registerAgentTools(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();const options={signal:controller.signal};const tools=[{name:'read_railway_game',title:'Consultar partida ferroviaria',description:'Lee el estado de la campaña sin modificarlo.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({month:state.month,date:E.dateOf(state.month),cash:state.cash,chapter:state.chapter,activeServices:state.routes.filter(r=>r.active).map(r=>({id:r.id,name:E.routeName(r),fleet:r.fleet,frequency:r.frequency})),pendingDecision:E.pendingDecision(state)?.id||null})},{name:'open_railway_service',title:'Abrir gestión de un servicio',description:'Muestra el panel del servicio y pausa el tiempo. No cambia su operación.',inputSchema:{type:'object',properties:{routeId:{type:'string'}},required:['routeId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.routeId!=='string'||!state.routes.some(r=>r.id===input.routeId))throw Error('Servicio desconocido.');selectRoute(input.routeId);return {selected:input.routeId};}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,options)).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
// Shared read-only snapshot is useful for accessibility integrations and reproducible verification.
window.railwayGame={snapshot:()=>JSON.parse(JSON.stringify(state)),navigate,engine:E,operations:O,gtfs:G,dayPlan:()=>JSON.parse(JSON.stringify(dayTrips)),reference:()=>({date:referenceDate,trips:referenceTrips.length,feed:referenceFeed?.name||null}),map};
render();intro();registerAgentTools();G.loadFeed().then(feed=>{if(feed){referenceFeed=feed;referenceDate=G.dateISO(feed.dateStart);referenceTrips=G.scheduleFor(feed,referenceDate);if(screen==='timetables')renderPanel();}});
